// Cloudflare Workers entry (wrangler.jsonc "main"; not used by Vercel or `next build`).
// It serves the app through the OpenNext worker and adds the scheduled pushes, which run
// here instead of as Vercel crons. Each cron calls its route in-process with the same
// Bearer token the route checks, so the routes behave exactly as when Vercel called them
// and can still be called by hand on either host.
// @ts-expect-error: generated by `npm run cf:build`
import worker from './.open-next/worker.js'

// @ts-expect-error: generated by `npm run cf:build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js'

// Must match "triggers.crons" in wrangler.jsonc character for character. Cloudflare counts
// weekdays from 1 = Sunday, so the weekly one is spelled SUN rather than 0.
const CRON_ROUTES = {
  '0 11 * * *':   '/api/push/daily',  // morning "today at a glance"
  '0 18 * * SUN': '/api/push/digest', // weekly digest
}

const handler = {
  fetch: worker.fetch,

  async scheduled(controller, env, ctx) {
    // A retry after a run that already sent some notifications would send them again.
    controller.noRetry?.()
    const path = CRON_ROUTES[controller.cron]
    if (!path) {
      console.warn(`cron "${controller.cron}" has no route`)
      return
    }
    const request = new Request(`https://luminae.lastivka.dev${path}`, {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
    })
    const res = await worker.fetch(request, env, ctx)
    console.log(`cron ${controller.cron} -> ${path}: ${res.status} ${(await res.text()).slice(0, 300)}`)
  },
}

export default handler
